public Money total() {
    if (!isValid()) {
        return Money.ZERO;
    }
    return discounted(subtotal());
}

private boolean isValid() { return !lines.isEmpty(); }
private Money subtotal() { return lines.stream().map(Line::amount).reduce(Money.ZERO, Money::add); }
private Money discounted(Money subtotal) { return subtotal.minus(discount); }
